-- Exercise translations (D15)
insert into public.exercise_translations
  (exercise_id, locale, name, alt_names, description, instructions, common_mistakes, media_alt)
select e.id, v.locale, v.name, v.alt_names, v.description, v.instructions, v.common_mistakes, v.media_alt
from (values
  ('abdominal-crunch', 'fr'::public.app_locale, 'Crunch abdominal', array['crunch', 'crunchs']::text[], 'Enroulement du buste au sol, de faible amplitude, qui cible les abdominaux.', '["Allonge-toi sur le dos, genoux pliés, pieds à plat au sol.","Place les mains sur la poitrine ou légèrement derrière la tête, sans tirer dessus.","Enroule le haut du dos pour décoller les omoplates du sol, en expirant.","Redescends lentement, sans reposer complètement la tête entre deux répétitions."]'::jsonb, '["Tirer sur la nuque avec les mains.","Monter trop haut en décollant le bas du dos.","Enchaîner vite avec de l’élan."]'::jsonb, 'Crunch abdominal : personne allongée sur le dos, genoux pliés, omoplates décollées du sol.'),
  ('abdominal-crunch', 'en'::public.app_locale, 'Abdominal crunch', array['crunch']::text[], 'A short curl of the upper body on the floor that targets the abs.', '["Lie on your back with knees bent and feet flat on the floor.","Place your hands on your chest or lightly behind your head, without pulling on it.","Curl your upper back to lift your shoulder blades off the floor as you breathe out.","Lower slowly, without fully resting your head between reps."]'::jsonb, '["Pulling on the neck with the hands.","Coming up so high that the lower back leaves the floor.","Rushing the reps with momentum."]'::jsonb, 'Abdominal crunch: a person lying on their back, knees bent, shoulder blades lifted off the floor.'),
  ('chin-up', 'fr'::public.app_locale, 'Chin-up (supination)', array['chin-up', 'chin-ups (supination)', 'traction en supination']::text[], 'Traction mains en supination, paumes vers toi. Les biceps travaillent davantage qu’en pronation.', '["Suspends-toi à la barre, paumes tournées vers toi, mains à la largeur des épaules.","Gaine le corps et garde les jambes immobiles.","Tire en amenant la poitrine vers la barre jusqu’à passer le menton au-dessus.","Redescends lentement jusqu’à avoir les bras tendus."]'::jsonb, '["Écarter les mains trop largement, ce qui gêne les poignets.","Balancer les jambes pour monter.","Remonter avant d’avoir les bras tendus en bas."]'::jsonb, 'Chin-up (supination) : personne suspendue à une barre, paumes vers elle, menton au-dessus de la barre.'),
  ('chin-up', 'en'::public.app_locale, 'Chin-up', array['underhand pull-up', 'supinated pull-up']::text[], 'A pull-up with an underhand grip, palms facing you. The biceps work more than with an overhand grip.', '["Hang from the bar with your palms facing you, hands shoulder-width apart.","Brace your body and keep your legs still.","Pull your chest towards the bar until your chin clears it.","Lower slowly until your arms are straight."]'::jsonb, '["Placing the hands too wide, which strains the wrists.","Swinging the legs to get up.","Starting the next rep before the arms are straight at the bottom."]'::jsonb, 'Chin-up: a person hanging from a bar with palms facing them, chin above the bar.'),
  ('hanging-knee-raise', 'fr'::public.app_locale, 'Relevé de genoux suspendu', array['relevés de genoux suspendu', 'relevé de genoux', 'hanging knee raise']::text[], 'Suspendu à la barre, tu montes les genoux pour renforcer les abdominaux sans prendre d’élan.', '["Suspends-toi à la barre, bras tendus, épaules légèrement abaissées.","Stabilise le corps pour ne pas te balancer.","Monte les genoux vers la poitrine en enroulant légèrement le bassin.","Redescends les jambes lentement, sous contrôle."]'::jsonb, '["Se balancer pour monter les jambes.","Laisser retomber les jambes d’un coup.","Monter les genoux sans enrouler le bassin."]'::jsonb, 'Relevé de genoux suspendu : personne suspendue à une barre, genoux montés à hauteur des hanches.'),
  ('hanging-knee-raise', 'en'::public.app_locale, 'Hanging knee raise', array['hanging knee tuck']::text[], 'Hanging from the bar, you raise your knees to build the abs without swinging.', '["Hang from the bar with straight arms, shoulders slightly drawn down.","Steady your body so you don’t swing.","Raise your knees towards your chest, tilting your pelvis slightly up.","Lower your legs slowly, under control."]'::jsonb, '["Swinging to lift the legs.","Letting the legs drop.","Raising the knees without tilting the pelvis."]'::jsonb, 'Hanging knee raise: a person hanging from a bar, knees raised to hip height.'),
  ('pike-push-up', 'fr'::public.app_locale, 'Pike push-up', array['pike push-ups', 'pompe pike', 'pompe en V']::text[], 'Pompe hanches hautes, en V inversé, qui oriente l’effort vers les épaules.', '["Mets-toi en position de pompe, puis recule les pieds et monte les hanches pour former un V inversé.","Garde les bras et les jambes aussi tendus que possible, la tête entre les bras.","Plie les coudes pour descendre le haut de la tête vers le sol, devant tes mains.","Pousse pour revenir bras tendus, hanches toujours hautes."]'::jsonb, '["Laisser les hanches descendre, ce qui transforme l’exercice en pompe classique.","Poser la tête au sol ou descendre trop vite.","Écarter fortement les coudes sur les côtés."]'::jsonb, 'Pike push-up : personne en V inversé, hanches hautes, mains et pieds au sol.'),
  ('pike-push-up', 'en'::public.app_locale, 'Pike push-up', array['pike press-up']::text[], 'A push-up with the hips high in an inverted V, which shifts the work to the shoulders.', '["Start in a push-up position, then walk your feet in and lift your hips into an inverted V.","Keep your arms and legs as straight as you can, head between your arms.","Bend your elbows to lower the top of your head towards the floor, just in front of your hands.","Press back up to straight arms, hips still high."]'::jsonb, '["Letting the hips drop, which turns it into a regular push-up.","Resting the head on the floor or lowering too fast.","Flaring the elbows wide to the sides."]'::jsonb, 'Pike push-up: a person in an inverted V, hips high, hands and feet on the floor.'),
  ('plank', 'fr'::public.app_locale, 'Planche', array['gainage', 'planche sur les avant-bras', 'plank']::text[], 'Gainage statique sur les avant-bras qui renforce la sangle abdominale et la stabilité du tronc.', '["Pose les avant-bras au sol, coudes sous les épaules, et tends les jambes derrière toi.","Décolle le corps pour former une ligne droite de la tête aux talons.","Serre les abdominaux et les fessiers, et respire calmement.","Tiens la position sans bouger jusqu’à la fin du temps prévu."]'::jsonb, '["Creuser le bas du dos en laissant le bassin descendre.","Monter les fesses trop haut.","Bloquer sa respiration."]'::jsonb, 'Planche : personne en appui sur les avant-bras et les pointes de pied, corps aligné.'),
  ('plank', 'en'::public.app_locale, 'Plank', array['forearm plank', 'front plank']::text[], 'A static hold on the forearms that builds the abdominal wall and trunk stability.', '["Place your forearms on the floor, elbows under your shoulders, and stretch your legs out behind you.","Lift your body into a straight line from head to heels.","Tighten your abs and glutes, and breathe steadily.","Hold still until the time is up."]'::jsonb, '["Arching the lower back by letting the hips sag.","Lifting the hips too high.","Holding your breath."]'::jsonb, 'Plank: a person supported on forearms and toes, body in a straight line.'),
  ('pull-up', 'fr'::public.app_locale, 'Traction stricte', array['traction', 'tractions strictes', 'pull-up']::text[], 'Tirage vertical au poids du corps, mains en pronation. Il renforce le dos et les bras, sans élan.', '["Suspends-toi à la barre, mains en pronation, un peu plus écartées que les épaules.","Serre les abdominaux et les fessiers pour garder le corps gainé et immobile.","Abaisse les épaules, puis tire en amenant la poitrine vers la barre jusqu’à passer le menton au-dessus.","Redescends lentement jusqu’à avoir les bras tendus, sans relâcher les épaules d’un coup."]'::jsonb, '["Prendre de l’élan avec les jambes ou le bassin.","S’arrêter à mi-hauteur au lieu de revenir bras tendus.","Tendre le cou pour passer le menton au lieu de tirer avec le dos."]'::jsonb, 'Traction stricte : personne suspendue à une barre, mains en pronation, menton au-dessus de la barre.'),
  ('pull-up', 'en'::public.app_locale, 'Pull-up', array['strict pull-up', 'traction']::text[], 'A bodyweight vertical pull with an overhand grip. It builds the back and arms, with no swinging.', '["Hang from the bar with an overhand grip, hands slightly wider than your shoulders.","Brace your abs and glutes so your body stays tight and still.","Draw your shoulders down, then pull your chest towards the bar until your chin clears it.","Lower slowly until your arms are straight, without dropping into the bottom."]'::jsonb, '["Swinging the legs or hips to build momentum.","Stopping halfway down instead of returning to straight arms.","Craning the neck to get the chin over instead of pulling with the back."]'::jsonb, 'Pull-up: a person hanging from a bar with an overhand grip, chin above the bar.'),
  ('push-up', 'fr'::public.app_locale, 'Pompe', array['pompes', 'push-up']::text[], 'Poussée horizontale au sol qui renforce la poitrine, les épaules et les triceps, corps gainé.', '["Place les mains au sol, un peu plus larges que les épaules, et tends les jambes derrière toi.","Aligne la tête, le dos et les talons, abdominaux et fessiers serrés.","Descends en pliant les coudes vers l’arrière, à environ 45° du corps, jusqu’à frôler le sol avec la poitrine.","Pousse dans le sol pour remonter bras tendus, sans casser l’alignement."]'::jsonb, '["Laisser le bassin s’affaisser ou le monter trop haut.","Écarter les coudes à 90° du corps.","Raccourcir l’amplitude au lieu de descendre près du sol."]'::jsonb, 'Pompe : personne en appui sur les mains et les pieds, corps aligné, bras tendus.'),
  ('push-up', 'en'::public.app_locale, 'Push-up', array['press-up', 'pompe']::text[], 'A horizontal push from the floor that builds the chest, shoulders and triceps, with the body braced.', '["Place your hands on the floor slightly wider than your shoulders and stretch your legs out behind you.","Line up your head, back and heels, with abs and glutes tight.","Lower by bending your elbows back at about 45° to your body until your chest nearly touches the floor.","Push the floor away to return to straight arms, keeping the line."]'::jsonb, '["Letting the hips sag or lifting them too high.","Flaring the elbows out to 90° from the body.","Cutting the range short instead of lowering close to the floor."]'::jsonb, 'Push-up: a person supported on hands and feet, body in a straight line, arms straight.'),
  ('side-plank', 'fr'::public.app_locale, 'Planche latérale', array['gainage latéral', 'side plank']::text[], 'Gainage sur le côté qui renforce les obliques et la stabilité du bassin. Le temps s’applique à chaque côté.', '["Allonge-toi sur le côté, avant-bras au sol, coude sous l’épaule, jambes tendues et pieds empilés.","Monte les hanches pour aligner la tête, le bassin et les pieds.","Garde le bassin face à l’avant, sans le laisser tourner ni descendre.","Tiens le temps prévu, puis change de côté."]'::jsonb, '["Laisser la hanche s’affaisser vers le sol.","Placer le coude loin de l’épaule.","Pencher le buste en avant ou en arrière."]'::jsonb, 'Planche latérale : personne sur le côté, en appui sur un avant-bras, hanches levées, corps aligné.'),
  ('side-plank', 'en'::public.app_locale, 'Side plank', array['lateral plank']::text[], 'A hold on your side that builds the obliques and pelvic stability. The time applies to each side.', '["Lie on your side with your forearm on the floor, elbow under your shoulder, legs straight and feet stacked.","Lift your hips so your head, pelvis and feet are in line.","Keep your pelvis facing forward, without letting it rotate or drop.","Hold for the set time, then switch sides."]'::jsonb, '["Letting the hip sag towards the floor.","Placing the elbow far from the shoulder.","Leaning the chest forwards or backwards."]'::jsonb, 'Side plank: a person on their side, supported on one forearm, hips lifted, body in a straight line.')
) as v (slug, locale, name, alt_names, description, instructions, common_mistakes, media_alt)
join public.exercises e on e.slug = v.slug
on conflict (exercise_id, locale) do update set
  name = excluded.name,
  alt_names = excluded.alt_names,
  description = excluded.description,
  instructions = excluded.instructions,
  common_mistakes = excluded.common_mistakes,
  media_alt = excluded.media_alt;

-- Variations and substitutes
delete from public.exercise_relations
where exercise_id in (select id from public.exercises where slug in ('abdominal-crunch', 'chin-up', 'hanging-knee-raise', 'pike-push-up', 'plank', 'pull-up', 'push-up', 'side-plank'));

insert into public.exercise_relations (exercise_id, related_exercise_id, kind)
select a.id, b.id, v.kind
from (values
  ('abdominal-crunch', 'plank', 'substitute'::public.exercise_relation_kind),
  ('chin-up', 'pull-up', 'variation'::public.exercise_relation_kind),
  ('hanging-knee-raise', 'abdominal-crunch', 'substitute'::public.exercise_relation_kind),
  ('hanging-knee-raise', 'plank', 'substitute'::public.exercise_relation_kind),
  ('pike-push-up', 'push-up', 'variation'::public.exercise_relation_kind),
  ('plank', 'side-plank', 'variation'::public.exercise_relation_kind),
  ('plank', 'abdominal-crunch', 'substitute'::public.exercise_relation_kind),
  ('pull-up', 'chin-up', 'variation'::public.exercise_relation_kind),
  ('push-up', 'pike-push-up', 'variation'::public.exercise_relation_kind),
  ('side-plank', 'plank', 'variation'::public.exercise_relation_kind)
) as v (slug, related_slug, kind)
join public.exercises a on a.slug = v.slug
join public.exercises b on b.slug = v.related_slug;

commit;
